import {useMutation} from '@github-ui/react-query'
import {reactFetch, reactFetchJSON} from '@github-ui/verified-fetch'
import {handleAgenticAutofixErrorResponse} from '../types/agentic-autofix-error'

export type AssignToCopilotRequest = {
  alertNumbers?: number[]
}

export type AssignToCopilotResponse = {
  jobId?: string
  agenticAutofixJobId?: string
}

export function useAssignToCopilotMutation(path: string) {
  return useMutation({
    mutationFn: async (request?: AssignToCopilotRequest): Promise<AssignToCopilotResponse> => {
      const response = request?.alertNumbers
        ? await reactFetchJSON(path, {
            method: 'POST',
            body: {
              alert_numbers: request.alertNumbers,
            },
          })
        : await reactFetch(path, {method: 'POST'})

      if (!response.ok) {
        await handleAgenticAutofixErrorResponse(response)
      }
      const contentType = response.headers.get('content-type')
      if (contentType?.includes('application/json')) {
        return (await response.json()) as AssignToCopilotResponse
      }
      return {}
    },
  })
}
